// Build entry point:  npm run build   (node build/build.js)
//
// Turns build/services-data.js + build/locations-data.js into every service,
// town, services, and locations page, plus sitemap.xml, robots.txt, and
// llms.txt, and keeps the shared header/footer and the home page's service
// grid and town chips in sync. Then it checks the SEO rules and every link.
//
// Generated files are overwritten on each build — never edit them by hand.

const fs = require("fs");
const path = require("path");

const cfg = require("./config");
const urls = require("./urls");
const seo = require("./seo");
const layout = require("./layout");
const { allPages, homeServiceCards, homeTownChips } = require("./pages");
const { checkLinks } = require("./check-links");
const { SERVICES } = require("./services-data");
const { TOWNS } = require("./locations-data");

const ROOT = cfg.ROOT_DIR;
const MANIFEST = path.join(__dirname, "generated-manifest.json");
const GENERATED_MARK = "GENERATED by build/build.js";

// Hand-made pages that get the shared header/footer injected.
const HAND_PAGES = [
  { file: "index.html", active: "home" },
  { file: "about.html", active: "about" },
  { file: "contact.html", active: "contact" },
];

const errors = [];
const warnings = [];

// ---------------------------------------------------------------- Clean-up

// Remove the folders a previous build created, so renamed or deleted
// services/towns do not leave stale pages behind. Only folders recorded in the
// manifest, and only if their index.html still carries the GENERATED mark.
function removePreviousOutput() {
  if (!fs.existsSync(MANIFEST)) return;
  const { dirs = [] } = JSON.parse(fs.readFileSync(MANIFEST, "utf8"));
  for (const name of dirs) {
    if (!/^[a-z0-9-]+$/.test(name)) continue;
    const dir = path.join(ROOT, name);
    const index = path.join(dir, "index.html");
    if (fs.existsSync(index) && fs.readFileSync(index, "utf8").includes(GENERATED_MARK)) {
      fs.rmSync(dir, { recursive: true });
    }
  }
}

// ------------------------------------------------------------ Page checks

// The SEO rules that apply to each finished page.
function checkPages(pages) {
  const titles = new Map();
  const descriptions = new Map();
  for (const p of pages) {
    if (p.title.length > 60) errors.push(`${p.path}: title is ${p.title.length} chars (max 60)`);
    if (p.description.length < 140 || p.description.length > 160) {
      warnings.push(`${p.path}: meta description is ${p.description.length} chars (target 145-155)`);
    }
    const h1Count = (p.html.match(/<h1[ >]/g) || []).length;
    if (h1Count !== 1) errors.push(`${p.path}: has ${h1Count} <h1> (needs exactly 1)`);
    if (!p.html.includes('rel="canonical"')) errors.push(`${p.path}: missing canonical`);
    if (titles.has(p.title)) errors.push(`${p.path}: duplicate title (also ${titles.get(p.title)})`);
    titles.set(p.title, p.path);
    if (descriptions.has(p.description)) errors.push(`${p.path}: duplicate meta description (also ${descriptions.get(p.description)})`);
    descriptions.set(p.description, p.path);
  }
}

// -------------------------------------------------------------- Injection

// Replace what sits between <!-- build:NAME:start --> and <!-- build:NAME:end -->.
function injectBlock(html, name, content, file) {
  const re = new RegExp(`(<!-- build:${name}:start -->)[\\s\\S]*?(<!-- build:${name}:end -->)`);
  if (!re.test(html)) {
    errors.push(`${file}: missing <!-- build:${name}:start/end --> markers`);
    return html;
  }
  return html.replace(re, `$1\n${content}\n$2`);
}

// Keep the shared header/footer, and the home page's grid and chips, in sync.
function syncHandPages() {
  for (const { file, active } of HAND_PAGES) {
    const full = path.join(ROOT, file);
    let html = fs.readFileSync(full, "utf8");
    html = injectBlock(html, "header", layout.headerBlock({ active, root: "" }), file);
    html = injectBlock(html, "footer", layout.footer({ root: "" }), file);
    if (file === "index.html") {
      html = injectBlock(html, "services-grid", homeServiceCards(), file);
      html = injectBlock(html, "town-chips", homeTownChips(), file);
    }
    fs.writeFileSync(full, html);
  }
}

// ------------------------------------------------------------- Pages index

// docs/ has to stay flat — the URL formula (/[service]-near-[town]/) is
// the whole point of the SEO strategy, so the generated pages can't be
// moved into a subfolder without changing every live URL. This writes a
// categorized, scannable index instead, so a person can find a page
// without counting through 168 folders. Lives next to the generator, not
// in docs/, since it's for developers, not site visitors.
const PAGES_INDEX = path.join(__dirname, "PAGES.md");

function writePagesIndex() {
  const lines = [
    "<!-- GENERATED by build/build.js. Do not edit by hand. -->",
    "# Generated pages",
    "",
    "docs/ has to stay flat for the URLs to work (see the home-service-SEO-",
    "strategy skill): every page below is a real directory directly under",
    "docs/, named exactly like its URL. This file is just an index so you",
    "can find one without scanning all of them in a file browser.",
    "",
    `${SERVICES.length} services × ${TOWNS.length} towns = ${SERVICES.length * TOWNS.length} service-in-town pages, plus ${SERVICES.length} no-town service pages and ${TOWNS.length} town hub pages.`,
    "",
    "## Service pages (no town)",
    "",
    ...SERVICES.map((s) => `- [${s.name}](../docs/${urls.service(s)}index.html) — \`/${urls.service(s)}\``),
    "",
    "## Town hub pages",
    "",
    ...TOWNS.map((t) => `- [${t.name}](../docs/${urls.townHub(t)}index.html) — \`/${urls.townHub(t)}\``),
    "",
    "## Service × town pages, grouped by service",
    "",
    ...SERVICES.flatMap((s) => [
      `### ${s.name} (${TOWNS.length} towns)`,
      "",
      ...TOWNS.map((t) => `- [${t.name}](../docs/${urls.serviceInTown(s, t)}index.html) — \`/${urls.serviceInTown(s, t)}\``),
      "",
    ]),
  ];
  fs.writeFileSync(PAGES_INDEX, lines.join("\n"));
}

// ------------------------------------------------------------------- Main

function main() {
  // 1. The copy rules, before anything is written.
  errors.push(...seo.validateData(SERVICES, TOWNS));
  if (errors.length) return report();

  // 2. Render every page and check it.
  removePreviousOutput();
  const pages = allPages();
  checkPages(pages);
  if (errors.length) return report(pages);

  // 3. Write the pages.
  for (const p of pages) {
    const target = path.join(ROOT, p.file);
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.writeFileSync(target, p.html);
  }
  const dirs = pages.filter((p) => p.file.endsWith("/index.html")).map((p) => p.file.split("/")[0]);
  fs.writeFileSync(MANIFEST, JSON.stringify({ dirs }, null, 2) + "\n");

  // 4. Hand-made pages, sitemap, robots, llms, and the dev-facing index.
  syncHandPages();
  writePagesIndex();
  const sitemapEntries = [
    { path: "", priority: "1.0" },
    { path: "contact.html", priority: "0.6" },
    { path: "about.html", priority: "0.5" },
    ...pages.map((p) => ({ path: p.path, priority: p.priority })),
  ];
  fs.writeFileSync(path.join(ROOT, "sitemap.xml"), seo.sitemapXml(sitemapEntries));
  fs.writeFileSync(path.join(ROOT, "robots.txt"), seo.robotsTxt());
  fs.writeFileSync(path.join(ROOT, "llms.txt"), seo.llmsTxt(SERVICES, TOWNS, urls));

  // 5. Every link must land on a real page.
  const { checked, broken } = checkLinks(ROOT);
  errors.push(...broken.map((b) => `broken link: ${b}`));

  report(pages, checked);
}

function report(pages = [], linksChecked = 0) {
  if (pages.length) {
    const byType = {};
    for (const p of pages) byType[p.type] = (byType[p.type] || 0) + 1;
    console.log(`Generated ${pages.length} pages:`);
    for (const [type, n] of Object.entries(byType)) console.log(`  ${String(n).padStart(4)}  ${type}`);
    const titleLens = pages.map((p) => p.title.length);
    const descLens = pages.map((p) => p.description.length);
    console.log(`Titles: max ${Math.max(...titleLens)} chars. Meta descriptions: ${Math.min(...descLens)}-${Math.max(...descLens)} chars.`);
    if (linksChecked) console.log(`Checked ${linksChecked} local links.`);
  }
  if (warnings.length) console.warn(`\n${warnings.length} warning(s):\n  ${warnings.slice(0, 15).join("\n  ")}${warnings.length > 15 ? "\n  ..." : ""}`);
  if (errors.length) {
    console.error(`\n${errors.length} ERROR(S):\n  ${errors.slice(0, 30).join("\n  ")}${errors.length > 30 ? "\n  ..." : ""}`);
    process.exit(1);
  }
  console.log("\nBuild OK.");
}

main();
